		previousNdcPosition = previousProjectedPosition.xy / previousProjectedPosition.w;
		screenUV = screenToUv(ndcPosition);
		depth = projectedPosition.z / projectedPosition.w;
		specPower = specularPower;
		specColor = specularColor * specularAmount;
		ndcPosition -= camera.jitterOffsets.xy;
		previousNdcPosition -= camera.jitterOffsets.zw;
		pixelVelocity = (previousNdcPosition - ndcPosition) * vec2(0.5, -0.5);
	};
	function vertex() {
		output.position = projectedPosition * vec4(1, camera.projFlip, 1, 1);
		pixelTransformedPosition = transformedPosition;
	};
	function fragment() {
		output.color = pixelColor;
		output.depth = depth;
		output.normal = transformedNormal;
		output.worldDist = worldDist;
		output.velocity = pixelVelocity;
	};
}

{
	@input var input:{ var position : Vec3; var normal : Vec3; var weights : Vec3; var indexes : Bytes4};
	var relativePosition:Vec3;
	@param var shapeCount:Int;
	@param var vcount:Int;
	@param var offsets:StorageBuffer<Float>;
	@param var weights:StorageBuffer<Float>;
	function vertex() {
		for (idx  in  0 ... shapeCount) {
			var offsetPos = vec3(offsets[(idx * vcount * 3) + (vertexID * 3)], offsets[(idx * vcount * 3) + (vertexID * 3) + 1], offsets[(idx * vcount * 3) + (vertexID * 3) + 2]);
			relativePosition = relativePosition + offsetPos * weights[idx];
		};
	};
}

{
	@param var inverseProj:Mat4;
	@param var texture:Sampler2D;
	@param var depthTexture:Sampler2D;
	@param @const var Quality:Int;
	@param @const var isDepth:Bool;
	@param var values:Array<Float,Quality>;
	@param var offsets:Array<Float,Quality>;
	@param var pixel:Vec2;
	@const var hasFixedColor:Bool;
	@const var smoothFixedColor:Bool;
	@param var fixedColor:Vec4;
	@param @const var isDepthDependant:Bool;
	@param var depthThreshold:Float = 1.0;
	@param var depthThresholdMaxDist:Float = 0.0;
	@param @const var isCube:Bool;
	@param var cubeTexture:SamplerCube;
	@param var cubeDir:Mat3;
	function scaleThreshold(z:Float):Float {
		var t = depthThreshold;
		if (depthThresholdMaxDist > 0.0) t *= 1.0 + max(z - depthThresholdMaxDist, 0.0);
		return t;
	};
	function fragment() {
		if (isDepthDependant) {
			var dimensions = texture.size();
			var invDimensions = 1.0 / dimensions;
			var coord = fragCoord.xy;
			var fragUV = coord.xy * invDimensions;
			var p = getViewPosition(fragUV);
			var minZ = p.z;
			var c = texture.get(fragUV);
			var color = vec4(0, 0, 0, 0);
			var isEdge = false;
			@unroll for (i  in  -Quality ... Quality + 1) {
				var curCoord = floor(coord + (pixel * dimensions) * i) + vec2(0.5);
				var nearestUV = curCoord * invDimensions;
				var pcur = getViewPosition(nearestUV);
				var d = abs(pcur.z - p.z);
				isEdge = isEdge || (d > scaleThreshold(min(pcur.z, p.z)));
			};
			@unroll for (i  in  -Quality + 1 ... Quality) {
				var curCoord = floor(coord + (pixel * dimensions) * offsets[i < 0 ? -i : i] * i) + vec2(0.5);
				var nearestUV = curCoord * invDimensions;
				var uv = fragUV + pixel * offsets[i < 0 ? -i : i] * i;
				var ccur = texture.get((isEdge) ? nearestUV : uv);
				var pcur = getViewPosition(nearestUV);
				var d = abs(pcur.z - p.z);
				c = (d > scaleThreshold(min(pcur.z, p.z))) ? c : ccur;
				color += c * values[i < 0 ? -i : i];
			};
			pixelColor = color;
		} else if (isDepth) {
			var val = 0.;
			@unroll for (i  in  -Quality + 1 ... Quality) {
				if (isCube) val += unpack(cubeTexture.get(vec3((input.uv + pixel * offsets[i < 0 ? -i : i] * i) * 2.0 - 1.0, 1) * cubeDir)) * values[i < 0 ? -i : i] else val += unpack(texture.get(input.uv + pixel * offsets[i < 0 ? -i : i] * i)) * values[i < 0 ? -i : i];
			};
			pixelColor = pack(val.min(0.9999999));
		} else {
			var color = vec4(0, 0, 0, 0);
			@unroll for (i  in  -Quality + 1 ... Quality) {
				if (isCube) color += cubeTexture.get(vec3((input.uv + pixel * offsets[i < 0 ? -i : i] * i) * 2.0 - 1.0, 1) * cubeDir) * values[i < 0 ? -i : i] else color += texture.get(input.uv + pixel * offsets[i < 0 ? -i : i] * i) * values[i < 0 ? -i : i];
			};
			pixelColor = color;
		};
		if (hasFixedColor) {
			if (smoothFixedColor) pixelColor.a *= fixedColor.a else pixelColor.a = fixedColor.a * float(pixelColor.a > 0);
			pixelColor.rgb = fixedColor.rgb * pixelColor.a;
		};
	};
	function getViewPosition(uv:Vec2):Vec3 {
		var depth = depthTexture.get(uv).r;
		var temp = vec4(uvToScreen(uv), depth, 1) * inverseProj;
		var originWS = temp.xyz / temp.w;
		return originWS;
	};
}

{
	@:extends h3d.shader.ShadowSampling;
	var pixelColor:Vec4;
	@global var camera:{ var view : Mat4};
	@const var enable:Bool;
	@const(2) var SAMPLING_MODE:Int;
	@const var DEBUG:Bool;
	@const var BLEND:Bool;
	@param var shadowPower:Float;
	@param var pcfScale:Float;
	var transformedPosition:Vec3;
	var shadow:Float;
	var dirShadow:Float;
	@param var cascadeShadowMaps:Sampler2DArray;
	@param var cascadeScales:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeOffsets:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeDebugs:Array<Vec4,MAX_CASCADE_COUNT>;
	@param var cascadeCount:Int;
	@param var cascadeViewProj:Mat3x4;
	@param var cascadeTransitionFraction:Float;
	function fragment() {
		if (enable) {
			var shadowValue = 1.0;
			var color = vec3(0);
			var viewZ = (transformedPosition * camera.view.mat3x4()).z;
			var shouldContinue = true;
			@unroll for (i  in  0 ... MAX_CASCADE_COUNT) if (i < cascadeCount) {
				if (shouldContinue && viewZ <= cascadeScales[i].w) {
					shouldContinue = false;
					var shadowPos0 = transformedPosition * cascadeViewProj;
					var shadowPos = (i == 0) ? shadowPos0 : cascadeShadowPos(shadowPos0, cascadeScales[i].xyz, cascadeOffsets[i].xyz);
					shadowValue = sampleCascadeArray(cascadeShadowMaps, i, shadowPos, 0.0, pcfScale, shadowPower, transformedPosition, SAMPLING_MODE);
					color = cascadeDebugs[i].rgb;
					if (BLEND) {
						var blendFactor = cascadeBlendFactor(viewZ, cascadeScales[i].w, cascadeTransitionFraction);
						if (blendFactor > 0.0) {
							if (i < MAX_CASCADE_COUNT - 1 && i < cascadeCount - 1) {
								var nextShadowPos = cascadeShadowPos(shadowPos0, cascadeScales[i + 1].xyz, cascadeOffsets[i + 1].xyz);
								var nextShadow = sampleCascadeArray(cascadeShadowMaps, i + 1, nextShadowPos, 0.0, pcfScale, shadowPower, transformedPosition, SAMPLING_MODE);
								shadowValue = nextShadow * blendFactor + shadowValue * (1 - blendFactor);
								var nextColor = cascadeDebugs[i + 1].rgb;
								color = nextColor * blendFactor + color * (1 - blendFactor);
							} else {
								shadowValue = blendFactor + shadowValue * (1 - blendFactor);
								color = color * (1 - blendFactor);
							};
						};
					};
				};
			};
			if (DEBUG) pixelColor = vec4(color, 1.0) else {
				shadow = shadowValue;
				dirShadow = shadow;
			};
		};
	};
}

{
	@param var source:Sampler2D;
	@param var texRatio:Float;
	var offsets:Array<Vec2,4> = [vec2(0, 0), vec2(0, 1), vec2(1, 0), vec2(1, 1)];
