		var linearLo = srgb * 0.0773993808;
		var linearHi = pow(srgb * 0.9478672986 + 0.0521327014, vec3(2.4));
		var linear = vec3(srgb.x <= 0.04045 ? linearLo.x : linearHi.x, srgb.y <= 0.04045 ? linearLo.y : linearHi.y, srgb.z <= 0.04045 ? linearLo.z : linearHi.z);
		return linear;
	};
	function linear2srgb(rgb:Vec3):Vec3 {
		var srgbLo = rgb * 12.92;
		var srgbHi = 1.055 * pow(rgb, vec3(0.41666)) - 0.055;
		var srgb = vec3(rgb.x <= 0.0031308 ? srgbLo.x : srgbHi.x, rgb.y <= 0.0031308 ? srgbLo.y : srgbHi.y, rgb.z <= 0.0031308 ? srgbLo.z : srgbHi.z);
