		transformedPosition = applySkinPoint(relativePosition);
		transformedNormal = applySkinVec(input.normal);
		transformedTangent.xyz = applySkinVec(input.tangent.xyz);
		transformedNormal = normalize(transformedNormal);
		transformedTangent.xyz = normalize(transformedTangent.xyz);
		var prevPosition = (relativePosition * getPrevBoneMatrix(input.indexes.x)) * skinWeights.x + (relativePosition * getPrevBoneMatrix(input.indexes.y)) * skinWeights.y + (relativePosition * getPrevBoneMatrix(input.indexes.z)) * skinWeights.z;
