		};
		counts |= typeCount << 8;
		typeCount = 0;
		for (l  in  capsuleStart ... capsuleEnd) {
			if (USE_OCCLUSION && lightVisible[capsuleSlot + l] == 0) continue;
			var i = capsuleLightOffset + l * CAPSULE_LIGHT_STRIDE;
			var halfLength = lightInfos[i].a;
			if (sphereTest(toView(lightInfos[i + 1].xyz), rangeFromInv4(lightInfos[i + 1].a) + halfLength)) pushLight(l);
		};
		counts |= typeCount << 16;
		typeCount = 0;
		for (l  in  rectStart ... rectEnd) {
			if (USE_OCCLUSION && lightVisible[rectSlot + l] == 0) continue;
			var i = rectLightOffset + l * RECT_LIGHT_STRIDE;
