	var DIR_LIGHT_STRIDE:Int = 2;
	var POINT_LIGHT_STRIDE:Int = 2;
	var SPOT_LIGHT_STRIDE:Int = 3;
	var CAPSULE_LIGHT_STRIDE:Int = 3;
	var RECT_LIGHT_STRIDE:Int = 6;
	var DIR_SHADOW_STRIDE:Int = 5;
