@param hideInAddMenu Hides the class from the add menu.
@param name The display name.
@param icon The icon.

PARAMS.expr:
{
	var m = new Map();
	for (p  in  emitterParams) m.set(p.name, p);
	for (p  in  instanceParams) m.set(p.name, p);
	m;
}

