{
	@param var color:Vec4;
	@:import h3d.shader.ColorSpaces;
	@const var reverseDepth:Bool;
	var output:{ var color : Vec4};
	function fragment() {
		var c = color.rgb;
		output.color.rgb = hsv2rgb(color.rgb);
		if (output.color.a < 0.01) discard;
		output.color.a = 1.0;
	};
}

{
	@param var texture:Sampler2D;
	function fragment() {
		var input = texture.get(calculatedUV);
		pixelColor.rgb = vec3((input.r + input.g + input.g) / 3.0);
	};
}

{
	@perInstance @param var randomParam:Float;
	var random:Float;
	function vertex() {
		random = randomParam;
	};
}

{
	@global var global:{ var time : Float};
	@global var camera:{ var position : Vec3};
	function random(pos:Vec2):Float {
		return fract(sin(dot(pos, vec2(12.9898, 78.233))) * 43758.5453123);
	};
	function random2d(pos:Vec2):Vec2 {
		return vec2(fract(sin(dot(pos, vec2(12.9898, 78.233))) * 43758.5453123), fract(sin(dot(pos, vec2(1572.9898, 132.237))) * 157468.33458));
	};
	function random3d(pos:Vec2):Vec3 {
		return vec3(fract(sin(dot(pos, vec2(12.9898, 78.233))) * 43758.5453123), fract(sin(dot(pos, vec2(1572.9898, 132.237))) * 157468.33458), fract(sin(dot(pos, vec2(14.5757, 59.147))) * 4756.281));
	};
	function identityMatrix():Mat4 {
		return mat4(vec4(1.0, 0.0, 0.0, 0.0), vec4(0.0, 1.0, 0.0, 0.0), vec4(0.0, 0.0, 1.0, 0.0), vec4(0.0, 0.0, 0.0, 1.0));
	};
	function translationMatrix(pos:Vec3):Mat4 {
		return mat4(vec4(1.0, 0.0, 0.0, pos.x), vec4(0.0, 1.0, 0.0, pos.y), vec4(0.0, 0.0, 1.0, pos.z), vec4(0.0, 0.0, 0.0, 1.0));
	};
	function scaleMatrix(scale:Vec3):Mat4 {
		return mat4(vec4(scale.x, 0.0, 0.0, 0.0), vec4(0.0, scale.y, 0.0, 0.0), vec4(0.0, 0.0, scale.z, 0.0), vec4(0.0, 0.0, 0.0, 1.0));
	};
	function sphericalToCartesian(radius:Float, theta:Float, phi:Float):Vec3 {
		var sTheta = sin(theta);
		return vec3(radius * sTheta * cos(phi), radius * sTheta * sin(phi), radius * cos(theta));
	};
	function cartesianToSpherical(pos:Vec3):Vec3 {
		var radius = length(pos);
		var dir = pos / radius;
		var theta = acos(pos.z / radius);
		var phi = atan(pos.y, pos.x);
		return vec3(radius, theta, phi);
	};
	function lookAtMatrix(eye:Vec3, at:Vec3, up:Vec3):Mat4 {
		var ax = normalize(at);
		var ay = cross(up, ax);
		if (dot(ay, ay) < 1e-6) {
			ay.x = ax.y;
			ay.y = ax.z;
			ay.z = ax.x;
		};
		ay = normalize(ay);
		var az = ax.cross(ay);
		var lookAt = mat4(vec4(ax.x, ay.x, az.x, eye.x), vec4(ax.y, ay.y, az.y, eye.y), vec4(ax.z, ay.z, az.z, eye.z), vec4(0.0, 0.0, 0.0, 1.0));
		return lookAt;
	};
	function alignMatrix(up:Vec3, dir:Vec3):Mat4 {
		var matrix = mat4(vec4(1.0, 0.0, 0.0, 0.0), vec4(0.0, 1.0, 0.0, 0.0), vec4(0.0, 0.0, 1.0, 0.0), vec4(0.0, 0.0, 0.0, 1.0));
		var rotationAxis = cross(up, dir);
		if (dot(rotationAxis, rotationAxis) > 1e-6) {
			rotationAxis = normalize(rotationAxis);
			var sinangle = -length(cross(dir, up));
			var cosangle = dot(up, dir);
			var cos1 = 1 - cosangle;
			var x = -rotationAxis.x;
			var y = -rotationAxis.y;
			var z = -rotationAxis.z;
			var xx = x * x;
			var yy = y * y;
			var zz = z * z;
			var xcos1 = x * cos1;
			var zcos1 = z * cos1;
			matrix = mat4(vec4(cosangle + x * xcos1, y * xcos1 - z * sinangle, x * zcos1 + y * sinangle, 0.0), vec4(y * xcos1 + z * sinangle, cosangle + yy * cos1, y * zcos1 - x * sinangle, 0.0), vec4(x * zcos1 - y * sinangle, y * zcos1 + x * sinangle, cosangle + z * zcos1, 0.0), vec4(0.0, 0.0, 0.0, 1.0));
		};
		return matrix;
	};
	function rotateMatrixX(angle:Float):Mat4 {
		return mat4(vec4(1.0, 0.0, 0.0, 0.0), vec4(0.0, cos(angle), -sin(angle), 0.0), vec4(0.0, sin(angle), cos(angle), 0.0), vec4(0.0, 0.0, 0.0, 1.0));
	};
	function rotateMatrixY(angle:Float):Mat4 {
		return mat4(vec4(cos(angle), 0.0, -sin(angle), 0.0), vec4(0.0, 1.0, 0.0, 0.0), vec4(sin(angle), 0.0, cos(angle), 0.0), vec4(0.0, 0.0, 0.0, 1.0));
	};
	function rotateMatrixZ(angle:Float):Mat4 {
		return mat4(vec4(cos(angle), -sin(angle), 0.0, 0.0), vec4(sin(angle), cos(angle), 0.0, 0.0), vec4(0.0, 0.0, 1.0, 0.0), vec4(0.0, 0.0, 0.0, 1.0));
	};
}

{
	@param var batchBuffer:RWPartialBuffer<{ var modelView : Mat4}>;
	@param var particleBuffer:RWPartialBuffer<{ var speed : Vec3; var life : Float; var lifeTime : Float; var random : Float; var color : Float}>;
	@:import h3d.shader.ColorSpaces;
	@const var FACE_CAM:Bool = false;
	@const var CAMERA_BOUNDS:Bool = false;
	@const var INFINITE:Bool = false;
	@param var dtParam:Float;
	@param var cameraUp:Vec3;
	@param var boundsPos:Vec3;
	@param var boundsSize:Vec3;
	@param var minSize:Float;
	@param var maxSize:Float;
	@param var curCount:Int;
	var dt:Float;
	var speed:Vec3;
	var life:Float;
	var lifeTime:Float;
	var particleRandom:Float;
	var particleColor:Vec4;
	var modelView:Mat4;
	var prevModelView:Mat4;
	var prevSpeed:Vec3;
	var relativeTransform:Mat4;
	var preventCameraWrap:Bool;
	var absoluteTranslation:Mat4;
	var prevPos:Vec3;
	var nextPos:Vec3;
	function __init__() {
		setLayout(64, 1, 1);
		absoluteTranslation = translationMatrix(vec3(0.0));
		preventCameraWrap = false;
		dt = dtParam;
		speed = particleBuffer[computeVar.globalInvocation.x].speed;
		life = particleBuffer[computeVar.globalInvocation.x].life;
		lifeTime = particleBuffer[computeVar.globalInvocation.x].lifeTime;
		prevModelView = batchBuffer[computeVar.globalInvocation.x].modelView;
		particleRandom = particleBuffer[computeVar.globalInvocation.x].random;
		particleColor = unpackIntColor(floatBitsToInt(particleBuffer[computeVar.globalInvocation.x].color));
		relativeTransform = scaleMatrix(((INFINITE || life < lifeTime) ? 1.0 : 0.0) * (computeVar.globalInvocation.x > curCount ? 0.0 : 1.0) * vec3(particleRandom * (maxSize - minSize) + minSize));
		prevPos = vec3(0.0) * prevModelView.mat3x4();
		nextPos = prevPos + speed * dt;
	};
	function main() {
		var align:Mat4;
		if (FACE_CAM) {
			align = lookAtMatrix(vec3(0.0), camera.position - prevPos, cameraUp);
		} else {
			align = rotateMatrixZ(computeVar.globalInvocation.x * 0.35487) * alignMatrix(vec3(0.0, 0.0, 1.0), normalize(speed));
		};
		modelView = relativeTransform * align * translationMatrix(nextPos) * absoluteTranslation;
		var idx = computeVar.globalInvocation.x;
		particleBuffer[idx].life = life + dt;
		particleBuffer[idx].speed = speed;
		particleBuffer[idx].color = intBitsToFloat(packIntColor(particleColor));
		batchBuffer[idx].modelView = modelView;
	};
}

{
	@param var batchBuffer:RWPartialBuffer<{ var modelView : Mat4}>;
	@param var particleBuffer:RWPartialBuffer<{ var speed : Vec3; var life : Float; var lifeTime : Float; var random : Float; var color : Float}>;
	@param var atomic:RWBuffer<Int>;
	@const var FORCED:Bool = false;
	@const var INFINITE:Bool = false;
	@const var SPEED_NORMAL:Bool;
	@param var minLifeTime:Float;
	@param var maxLifeTime:Float;
	@param var minStartSpeed:Float;
	@param var maxStartSpeed:Float;
	@param var rate:Int;
	@param var absPos:Mat4;
	@:import h3d.shader.ColorSpaces;
	var life:Float;
	var particleRandom:Float;
	var modelView:Mat4;
	var relativeTransform:Mat4;
	var emitNormal:Vec3;
	var particleColor:Vec4;
	function __init__() {
		setLayout(64, 1, 1);
		emitNormal = vec3(0.0, 0.0, 1.0);
		particleRandom = particleBuffer[computeVar.globalInvocation.x].random;
		life = mix(minLifeTime, maxLifeTime, (global.time + particleRandom) % 1.0);
		relativeTransform = translationMatrix(vec3(0.0));
		modelView = absPos * relativeTransform;
		particleColor = vec4(1.0);
	};
	function main() {
		var idx = computeVar.globalInvocation.x;
		var curLife = particleBuffer[idx].life;
		var curLifeTime = particleBuffer[idx].lifeTime;
		if (FORCED || (!INFINITE && curLife > curLifeTime)) {
			var c = atomicAdd(atomic, 0, 1);
			if (FORCED || (!INFINITE && c < rate)) {
				batchBuffer[idx].modelView = modelView;
				var s = vec3(0.0, 0.0, 1.0);
				if (SPEED_NORMAL) s = emitNormal;
				particleBuffer[idx].speed = s * maxStartSpeed;
				particleBuffer[idx].life = 0.0;
				particleBuffer[idx].lifeTime = life;
				particleBuffer[idx].color = intBitsToFloat(packIntColor(particleColor));
			};
		};
	};
}

{
	@param var boundsPos:Vec3;
	@param var boundsSize:Vec3;
	var nextPos:Vec3;
	var preventCameraWrap:Bool;
	function __init__() {
		preventCameraWrap = false;
	};
	function main() {
		if (!preventCameraWrap) {
			if (!preventCameraWrap) {
				nextPos = ((nextPos - boundsPos) % boundsSize) + boundsPos;
			};
		};
	};
}

{
	@param var boundsMin:Vec3;
	@param var boundsSize:Vec3;
	var particleRandom:Float;
	var relativeTransform:Mat4;
	function main() {
		var rnd = random3d(vec2(global.time + particleRandom, particleRandom * 100.0));
		relativeTransform = translationMatrix(rnd * boundsSize + boundsMin);
	};
}

{
	@param var minRadius:Float;
	@param var maxRadius:Float;
	var emitNormal:Vec3;
	var relativeTransform:Mat4;
	function main() {
		var rnd = random2d(vec2(global.time, computeVar.globalInvocation.x));
		var theta = rnd.y * 2.0 * PI;
		var dir = vec3(cos(theta), sin(theta), 0.0);
		emitNormal = dir;
		relativeTransform = translationMatrix(dir * mix(minRadius, maxRadius, rnd.x));
	};
}

{
	@param var absPos:Mat4;
	@param var particleBuffer:RWPartialBuffer<{ var life : Float; var lifeTime : Float; var random : Float; var color : Float}>;
	@:import h3d.shader.ColorSpaces;
	@flat var particleLife:Float;
	@flat var particleLifeTime:Float;
	@flat var particleRandom:Float;
	@flat var particleColor:Vec4;
	@param var meshTransform:Mat4;
	@param var meshTransformInverse:Mat4;
	var meshToModel:Mat4;
	var modelToMesh:Mat4;
	var transformedPosition:Vec3;
	function __init__vertex() {
		{
			particleLife = particleBuffer[instanceID].life;
			particleLifeTime = particleBuffer[instanceID].lifeTime;
			particleRandom = particleBuffer[instanceID].random;
			particleColor = unpackIntColor(floatBitsToInt(particleBuffer[instanceID].color));
		};
		meshToModel = meshTransform;
		modelToMesh = meshTransformInverse;
		transformedPosition = transformedPosition * absPos.mat3x4();
	};
	var pixelColor:Vec4;
	function fragment() {
		pixelColor *= particleColor;
	};
}

{
	@param var gravity:Vec3;
	var speed:Vec3;
	var dt:Float;
	function main() {
		speed += dt * gravity * 9.81;
	};
}

{
	@param var speedRotation:Float;
	var relativeTransform:Mat4;
	var dt:Float;
	var life:Float;
	var particleRandom:Float;
	function main() {
		var r = 2.0 * random3d(vec2(particleRandom)) - 1.0;
		relativeTransform = rotateMatrixX(speedRotation * life * r.x) * rotateMatrixY(speedRotation * life * r.y) * rotateMatrixZ(speedRotation * life * r.z) * relativeTransform;
	};
}

{
	@const(1024) var JOINTS_BUFFER_SIZE:Int;
	@param var vertexCount:Int;
	@param var vbuf:RWPartialBuffer<{ var position : Vec3; var padding : Float; var normal : Vec3; var padding2 : Float; var weights : Vec3; var indexes : Bytes4}>;
	@param var absPosInv:Mat3x4;
	@param var bonesMatrixes:Buffer<Vec4,JOINTS_BUFFER_SIZE>;
	var speed:Vec3;
	var emitNormal:Vec3;
	var relativeTransform:Mat4;
	function main() {
		var idx = computeVar.globalInvocation.x;
		var vertexId = int(random(float(idx).xx) * vertexCount);
		var vertexData = vbuf[vertexId];
		speed = vec3(1.0);
		var relativePosition = vertexData.position;
		var relativeNormal = vertexData.normal;
		var weights = vertexData.weights;
		var transformedPosition = (relativePosition * getBoneMatrix(vertexData.indexes.x * 127.0) * absPosInv) * weights.x + (relativePosition * getBoneMatrix(vertexData.indexes.y * 127.0) * absPosInv) * weights.y + (relativePosition * getBoneMatrix(vertexData.indexes.z * 127.0) * absPosInv) * weights.z;
		var transformedNormal = (vertexData.normal * absPosInv.mat3() * mat3(getBoneMatrix(vertexData.indexes.x * 127.0))) * vertexData.weights.x + (vertexData.normal * absPosInv.mat3() * mat3(getBoneMatrix(vertexData.indexes.y * 127.0))) * vertexData.weights.y + (vertexData.normal * absPosInv.mat3() * mat3(getBoneMatrix(vertexData.indexes.z * 127.0))) * vertexData.weights.z;
		emitNormal = transformedNormal;
		relativeTransform = translationMatrix(transformedPosition);
	};
	function getBoneMatrix(index:Float):Mat3x4 {
		var i = int(index) * 3;
		return mat3x4(bonesMatrixes[i], bonesMatrixes[i + 1], bonesMatrixes[i + 2]);
	};
}

{
	@param var axis:Vec3;
	@param var center:Vec3;
	var speed:Vec3;
	var prevModelView:Mat4;
	var modelView:Mat4;
	var dt:Float;
	function main() {
		var idx = computeVar.globalInvocation.x;
		var prevPos = vec3(0.0) * prevModelView.mat3x4();
		var radialDir = prevPos - center;
		var radius = length(radialDir);
		radialDir = radialDir - radialDir.dot(axis) * axis;
		radialDir = normalize(radialDir);
		var spherical = cartesianToSpherical(radialDir);
		var theta = spherical.y;
		var phi = spherical.z + PI * 0.5;
		speed = vec3(sin(theta) * cos(phi), sin(theta) * sin(phi), cos(theta)) / radius;
		var newPos = normalize(prevPos + dt * speed) * radius;
		speed = (newPos - prevPos) / dt;
	};
}

{
	@param var batchBuffer:RWPartialBuffer<{ var previousModelView : Mat4}>;
	var prevModelView:Mat4;
	function main() {
		var idx = computeVar.globalInvocation.x;
		batchBuffer[idx].previousModelView = prevModelView;
	};
}

{
	@param var color1:Int;
	@param var color2:Int;
	@:import h3d.shader.ColorSpaces;
	var particleRandom:Float;
	var particleColor:Vec4;
	function main() {
		var idx = computeVar.globalInvocation.x;
		var fromColor = unpackIntColor(color1);
		var toColor = unpackIntColor(color2);
		particleColor = mix(fromColor, toColor, particleRandom);
	};
}

{
	@const(511) var CURVE_MASK:Int;
	@param var x:Float;
	@param var y:Float;
	@param var z:Float;
	@param var scaleX:Float;
	@param var scaleY:Float;
	@param var scaleZ:Float;
	@param var rotX:Float;
	@param var rotY:Float;
	@param var rotZ:Float;
	@param var speedX:Float;
	@param var speedY:Float;
	@param var speedZ:Float;
	@param var curveTexture:Sampler2D;
	var life:Float;
	var lifeTime:Float;
	var relativeTransform:Mat4;
	var dt:Float;
	function hasBit(n:Int):Bool {
		return (CURVE_MASK & (1 << n)) != 0;
	};
	function getCurve(n:Int, l:Float):Float {
		var c = 0.0;
		if (CURVE_MASK != 0) c = curveTexture.getLod(vec2(l / lifeTime, (n + 0.5) / 9.0), 0.0).r;
		return c;
	};
	function getDiff(n:Int):Float {
		return getCurve(n, life + dt) - getCurve(n, life);
	};
	function main() {
		var justAlive = life <= 0.0;
		var translation = justAlive ? vec3(x, y, z) : vec3(0.0);
		var scale = vec3(scaleX, scaleY, scaleZ);
		var rotation = vec3(rotX, rotY, rotZ);
		var speed = vec3(speedX, speedY, speedZ);
		if (hasBit(0)) translation.x = justAlive ? getCurve(0, life) : getDiff(0);
		if (hasBit(1)) translation.y = justAlive ? getCurve(1, life) : getDiff(1);
		if (hasBit(2)) translation.z = justAlive ? getCurve(2, life) : getDiff(2);
		if (hasBit(3)) scale.x = getCurve(3, life);
		if (hasBit(4)) scale.y = getCurve(4, life);
		if (hasBit(5)) scale.z = getCurve(5, life);
		if (hasBit(6)) rotation.x = getCurve(6, life);
		if (hasBit(7)) rotation.y = getCurve(7, life);
		if (hasBit(8)) rotation.z = getCurve(8, life);
		var shaderTRS = scaleMatrix(scale) * translationMatrix(translation) * translationMatrix(speed);
		relativeTransform = relativeTransform * shaderTRS;
	};
}

{
	@param var minRadius:Float;
	@param var maxRadius:Float;
	@param var randOffset:Int;
	var emitNormal:Vec3;
	var relativeTransform:Mat4;
	function main() {
		var rnd = random3d(vec2(global.time, computeVar.globalInvocation.x + randOffset));
		var theta = rnd.y * PI;
		var phi = rnd.z * 2.0 * PI;
		var dir = sphericalToCartesian(1.0, theta, phi);
		emitNormal = dir;
		relativeTransform = translationMatrix(dir * mix(minRadius, maxRadius, rnd.x));
	};
}

{
	@param var intensity:Float;
	@const var octaves:Int;
	@param var noiseTex:Sampler2D;
	@param var noiseScale:Float;
	@param var scrollSpeed:Vec3;
	@param var innerTurmoil:Float;
	@param var lacunarity:Float;
	@param var persistence:Float;
	var speed:Vec3;
	var prevModelView:Mat4;
	var modelView:Mat4;
	var dt:Float;
	function noise(pos:Vec3):Float {
		var i = floor(pos);
		var f = fract(pos);
		f = f * f * (3.0 - 2.0 * f);
		var uv = (i.xy + vec2(37.0, 239.0) * i.z) + f.xy;
		var rg = noiseTex.getLod((uv + 0.5) / 256.0, 0).yx;
		return 2.0 * mix(rg.x, rg.y, f.z) - 1.0;
	};
	function noiseAt(pos:Vec3):Float {
		var amount = 0.;
		var tot = 0.;
		var pos = pos * 0.1 * noiseScale;
		var k = 1.;
		var t = global.time * scrollSpeed;
		@unroll for (i  in  0 ... octaves) {
			var staticOffset = vec3(0, 0, 1);
			var f = 1.0;
			if (i == 0) {
				f = 0.5;
				amount += noise(pos - t - staticOffset * global.time * innerTurmoil) * k * f;
			};
			staticOffset = vec3(0, 0, -1);
			if (i == 1) staticOffset = vec3(0, 0, -0.6);
			if (i == 2) staticOffset = vec3(-0.9, 0, 1.1);
			if (i == 3) staticOffset = vec3(0.8, 0.95, -1.2);
			if (i == 4) staticOffset = vec3(0, -0.84, -1.3);
			if (i == 5) staticOffset = vec3(0.3, -0.05, -0.9);
			amount += noise(pos - t - staticOffset * global.time * innerTurmoil) * k * f;
			tot += k;
			pos *= lacunarity;
			k *= persistence;
		};
		return amount / tot;
	};
	function main() {
		var idx = computeVar.globalInvocation.x;
		var prevPos = vec3(0.0) * prevModelView.mat3x4();
		var n = noiseAt(prevPos);
		speed += normalize(scrollSpeed) * n * intensity;
	};
}

{
	@param var batchBuffer:RWBuffer<Float>;
	@param var particleBuffer:RWPartialBuffer<{ var life : Float; var lifeTime : Float}>;
	@param var paramTexture:Sampler2D;
	@param var stride:Int;
	@param var pos:Int;
	@param var row:Float;
	function main() {
		setLayout(64, 1, 1);
		var idx = computeVar.globalInvocation.x;
		batchBuffer[idx * stride + pos] = paramTexture.getLod(vec2(1.0 - particleBuffer[idx].life / particleBuffer[idx].lifeTime, row), 0.0).x;
	};
}

{
	@:import h3d.shader.NoiseLib;
	@const(5) var channels:Int = 1;
	@const(64) var octaves:Int = 1;
	@const(4) var mode:Int;
	@const var normals:Bool;
	@const(4) var repeat:Int;
	@param var seed:Int;
	@param var scale:Float = 8;
	@param var persist:Float = 0.5;
	@param var lacunarity:Float = 2.0;
	@param var gain:Float;
	@param var offset:Float;
	@param var inverse:Float;
	@param var contrast:Float;
	@param var brightness:Float;
	@param var turbulence:Float;
	@param var turbulenceScale:Float;
	function makeRepeat(scale:Float):Vec2 {
		var s = int(scale * 0.5) * 2.;
