			var cb = rgb2ycocg(curFrame.getLod(calculatedUV + (vec2(0.0, -1.0) * invResolution), 0).rgb);
			var rb = rgb2ycocg(curFrame.getLod(calculatedUV + (vec2(1.0, -1.0) * invResolution), 0).rgb);
