		var h2 = heightMap.get(calculatedUV + vec2(pixelSize.x, 0)).r;
		var h3 = heightMap.get(calculatedUV + vec2(0, -pixelSize.y)).r;
		var h4 = heightMap.get(calculatedUV + vec2(-pixelSize.x, 0)).r;
