		var i2:Int = int(texIndex.g * 255);
		var i3:Int = int(texIndex.b * 255);
		if (i1 == index) pixelColor = vec4(vec3(packedWeightTexture.get(calculatedUV).r), 1.0) else if (i2 == index) pixelColor = vec4(vec3(packedWeightTexture.get(calculatedUV).g), 1.0) else if (i3 == index) pixelColor = vec4(vec3(packedWeightTexture.get(calculatedUV).b), 1.0);
	};
