{
	@global var global:{ @perObject
	var modelView : Mat4};
	@const var NORMAL:Bool = false;
	@const var NORMAL_FLIP_Y:Bool = false;
	@const var NORMAL_FLIP_X:Bool = false;
	@const var VERTEX:Bool = true;
	@param var directLightingIntensity:Float;
	@param var indirectLightingIntensity:Float;
	@param var normalMap:Sampler2D;
	@param var normalIntensity:Float;
	var calculatedUV:Vec2;
	var localNormal:Vec3;
	var localTangent:Vec3;
	var backLightingIntensity:Float;
	@param var hl2_basis0:Vec3;
	@param var hl2_basis1:Vec3;
	@param var hl2_basis2:Vec3;
	var hl2_basis0Transformed:Vec3;
	var hl2_basis1Transformed:Vec3;
	var hl2_basis2Transformed:Vec3;
	var color0:Vec3;
	var color1:Vec3;
	var color2:Vec3;
	var lighting:Vec3;
	function indirectLighting():Vec3 {
		var indirect = vec3(0);
		if (NORMAL && VERTEX) {
			var rotatedNormal = rotateNormal(transformedNormal);
			var diffuse = irrDiffuse.get(rotatedNormal).rgb;
			color0 += diffuse * irrPower * indirectLightingIntensity;
			color1 += diffuse * irrPower * indirectLightingIntensity;
			color2 += diffuse * irrPower * indirectLightingIntensity;
		} else {
			var rotatedNormal = rotateNormal(transformedNormal);
			var diffuse = irrDiffuse.get(rotatedNormal).rgb;
			indirect += diffuse * irrPower * indirectLightingIntensity;
		};
		return indirect;
	};
	function directLighting(lightColor:Vec3, lightDirection:Vec3, specularDirection:Vec3):Vec3 {
		var result = vec3(0);
		if (NORMAL && VERTEX) {
			var localBitangent = normalize(localNormal.cross(vec3(localTangent.x, localTangent.y, localTangent.z)));
			var TBN = mat3(vec3(localTangent.x, localBitangent.x, localNormal.x), vec3(localTangent.y, localBitangent.y, localNormal.y), vec3(localTangent.z, localBitangent.z, localNormal.z));
			hl2_basis0Transformed = normalize(hl2_basis0 * TBN * global.modelView.mat3());
			hl2_basis1Transformed = normalize(hl2_basis1 * TBN * global.modelView.mat3());
			hl2_basis2Transformed = normalize(hl2_basis2 * TBN * global.modelView.mat3());
			var weights = saturate(vec3(lightDirection.dot(hl2_basis0Transformed), lightDirection.dot(hl2_basis1Transformed), lightDirection.dot(hl2_basis2Transformed)));
			color0 += weights.x * lightColor * directLightingIntensity;
			color1 += weights.y * lightColor * directLightingIntensity;
			color2 += weights.z * lightColor * directLightingIntensity;
		} else {
			var NdL = transformedNormal.dot(lightDirection);
			result += lightColor * clamp(NdL, 0.0, 1.0);
		};
		var bNdL = clamp(-transformedNormal.dot(lightDirection), 0.0, 1.0);
		result += lightColor * bNdL * backLightingIntensity;
		return result * directLightingIntensity;
	};
	function evaluateLighting():Vec3 {
		var lightAccumulation = vec3(0);
		color0 = vec3(0);
		color1 = vec3(0);
		color2 = vec3(0);
		for (l  in  0 ... dirLightCount) lightAccumulation += evaluateDirLight(l);
		for (l  in  0 ... pointLightCount) lightAccumulation += evaluatePointLight(l);
		for (l  in  0 ... spotLightCount) lightAccumulation += evaluateSpotLight(l);
		if (USE_INDIRECT) lightAccumulation += indirectLighting();
		return lightAccumulation;
	};
	function normalMapping() {
		var n = unpackNormal(normalMap.get(calculatedUV).rgba);
		n = vec3(NORMAL_FLIP_X ? -n.x : n.x, NORMAL_FLIP_Y ? -n.y : n.y, n.z);
		var localBitangent = normalize(localNormal.cross(vec3(localTangent.x, localTangent.y, localTangent.z)));
		var TBN = mat3(vec3(localTangent.x, localBitangent.x, localNormal.x), vec3(localTangent.y, localBitangent.y, localNormal.y), vec3(localTangent.z, localBitangent.z, localNormal.z));
		transformedNormal = mix(transformedNormal, normalize(n * TBN * global.modelView.mat3()), normalIntensity);
	};
	function init() {
		if (NORMAL && !VERTEX) normalMapping();
		view = (cameraPosition - transformedPosition).normalize();
		NdV = transformedNormal.dot(view).max(0.);
	};
	function vertex() {
		if (VERTEX) {
			init();
			lighting = evaluateLighting();
		};
	};
	function fragment() {
		if (VERTEX && NORMAL) {
			normalMapping();
			var w = saturate(vec3(transformedNormal.dot(hl2_basis0Transformed), transformedNormal.dot(hl2_basis1Transformed), transformedNormal.dot(hl2_basis2Transformed)));
			lighting += color0 * w.x + color1 * w.y + color2 * w.z;
		} else if (!VERTEX) {
			init();
			lighting = evaluateLighting();
		};
		output.color.rgb *= lighting;
	};
}

{
	@:import hrt.shader.BaseEmitter;
	@const @param var axis:hrt.shader.ParticleRandomMesh.ParticleRandomMeshAxis = PosX;
	@range(1, 32) @param var cellCount:Int = 4;
	@range(0, 10) @param var cellSize:Float = 1.0;
	@const @param var recenter:Bool = true;
	function vertex() {
		var s = (axis == NegX || axis == NegY || axis == NegZ) ? -1.0 : 1.0;
		var dir = axis.toInt() < PosY.toInt() ? vec3(s, 0.0, 0.0) : (axis.toInt() < PosZ.toInt() ? vec3(0.0, s, 0.0) : vec3(0.0, 0.0, s));
		var count = max(float(cellCount), 1.0);
		var cell = min(floor(particleRandom * count), count - 1.0);
		var pos = relativePosition * meshToModel.mat3x4();
		var start = cell * cellSize;
		var local = dot(pos, dir) - start;
		if (local < 0.0 || local > cellSize) pos = vec3(0.0) else pos -= dir * (recenter ? start + cellSize * 0.5 : start);
		relativePosition = pos * modelToMesh.mat3x4();
	};
}

{
	@param var scale:Vec2 = vec2(16.0);
	@param var split:Vec4 = vec4(0.0, 0.0, 1.0, 1.0);
	var absolutePosition:Vec4;
	var calculatedUV:Vec2;
	var pixelColor:Vec4;
	function fragment() {
		if (calculatedUV.x >= split.x && calculatedUV.y >= split.y && calculatedUV.x <= split.z && calculatedUV.y <= split.w) {
			var cb = floor(mod(absolutePosition.xy / scale, vec2(2.0)));
			var check = mod(cb.x + cb.y, 2.0);
			var color = check >= 1.0 ? vec3(0.22) : vec3(0.44);
			pixelColor.rgb = mix(color, pixelColor.rgb, pixelColor.a);
		};
		pixelColor.a = 1.0;
	};
}

{
	@param var intensityInput:Float;
	@param var albedoMultInput:Float;
	var intensity:Float;
	var albedoMult:Float;
	function fragment() {
		intensity = intensityInput;
		albedoMult = albedoMultInput;
	};
}

{
	var calculatedUV:Vec2;
	var pixelColor:Vec4;
	@param var sampler:Sampler2D;
	@param var pxRange:Float;
	@param var bgColor:Vec4;
	@param var fgColor:Vec4;
	function screenPxRange():Float {
		var unitRange = vec2(pxRange) / vec2(sampler.size());
		var screenTexSize = vec2(1.0) / fwidth(calculatedUV);
		return max(0.5 * dot(unitRange, screenTexSize), 1.0);
	};
	function fragment() {
		var distance:Float = sampler.get(calculatedUV).r;
		var sceenPxDistance = screenPxRange() * (distance - 0.5);
		var opacity:Float = clamp(sceenPxDistance + 0.5, 0.0, 1.0);
		pixelColor = mix(bgColor, fgColor, opacity);
		pixelColor.a *= opacity;
	};
}

{
	var albedoGamma:Vec3;
	var customSpecularColor:Vec3;
	function fragment() {
		customSpecularColor = albedoGamma;
	};
}

{
	@param var specularColorValue:Vec3;
	var customSpecularColor:Vec3;
	function fragment() {
		customSpecularColor = specularColorValue;
