{
	@param var specularColorTexture:Sampler2D;
	var customSpecularColor:Vec3;
	var calculatedUV:Vec2;
	function fragment() {
		customSpecularColor = specularColorTexture.get(calculatedUV % 1.0).rgb;
	};
}

{
	@param var specular:Float;
	@param var specularTint:Float;
	var customSpecularColor:Vec3;
	var pbrSpecularColor:Vec3;
	function fragment() {
		pbrSpecularColor = mix(vec3(1.0), customSpecularColor, specularTint) * vec3(specular * 0.08);
	};
}

{
	var pixelColor:Vec4;
	@param var shapeSDF:Sampler2D;
	@param var trailTexture:Sampler2D;
	@param var scaleX:Float = 1.0;
	@param var scaleY:Float = 1.0;
	@param var scaleTime:Float = 1.0;
	@param var timeOffset:Float = 0.0;
	@const var correctTextureNormals:Bool = false;
	@param var numTrails:Float = 3;
	@const var useTimeTexture:Bool = false;
	@param var timeTexture:Sampler2D;
	@const var debugShowShape:Bool = false;
	@global var global:{ var time : Float};
	var calculatedUV:Vec2;
	function dist(uv:Vec2):Float {
		var c = shapeSDF.get(uv);
		return max(min(c.r, c.b), min(max(c.r, c.g), c.b)) - 0.5;
	};
	function fragment() {
		var uv = calculatedUV;
		var sdf = dist(uv);
		var uvSurface = calculatedUV - vec2(0.5);
		if (correctTextureNormals) {
			var dd = vec3(1.0 / shapeSDF.size().x, 1.0 / shapeSDF.size().y, 0.0);
			var norm = normalize(vec2(dist(uv + dd.xz) - dist(uv - dd.xz), dist(uv + dd.zy) - dist(uv - dd.zy)));
			uvSurface -= norm * sdf * 0.25;
		};
		var g = useTimeTexture ? timeTexture.get(uv).r : atan(uvSurface.y, uvSurface.x) / (2 * 3.1415) + 0.5;
		var trueTime = global.time * scaleTime + timeOffset;
		var t = g - mod(trueTime, 1.0);
		t = 1.0 - mod(t, 1.0);
		t = mod(t * numTrails, 1.0);
		var uvLocal = vec2(1.0 - t, ((scaleY - sdf) / scaleY) / 2.0);
		uvLocal.x = 1.0 - (1.0 - uvLocal.x) / scaleX;
		uvLocal = clamp(uvLocal, vec2(0.01), vec2(1.0));
		var trail = trailTexture.get(uvLocal);
		if (debugShowShape) {
			pixelColor = mix(trail, vec4(1.0), 1.0 - smoothstep(0.0, 0.01, abs(sdf)));
		} else {
			pixelColor = trail;
		};
	};
}

{
	@const var GLOSS:Bool = true;
	@const var SHOW_GRID:Bool;
	@const var SURFACE_COUNT:Int;
	@const var CHECKER:Bool;
	@const var COMPLEXITY:Bool;
	@const var PARALLAX:Bool;
	@const var VERTEX_DISPLACEMENT:Bool;
	@param var primSize:Vec2;
	@param var cellSize:Vec2;
	@param var heightMapSize:Vec2;
	@param var albedoTextures:Sampler2DArray;
	@param var normalTextures:Sampler2DArray;
	@param var pbrTextures:Sampler2DArray;
	@param var weightTextures:Sampler2DArray;
	@param var surfaceIndexMap:Sampler2D;
	@param var heightMap:Sampler2D;
	@param var normalMap:Sampler2D;
	@param var surfaceParams:Array<Vec4,SURFACE_COUNT>;
	@param var secondSurfaceParams:Array<Vec4,SURFACE_COUNT>;
	@param var heightBlendStrength:Float;
	@param var blendSharpness:Float;
	@param var parallaxAmount:Float;
	@param var minStep:Int;
	@param var maxStep:Int;
	@param var tileIndex:Vec2;
	var worldUV:Vec2;
	var calculatedUV:Vec2;
	var TBN:Mat3;
	var emissive:Float;
	var metalness:Float;
	var roughness:Float;
	var occlusion:Float;
	var tangentViewPos:Vec3;
	var tangentFragPos:Vec3;
	var transformedPosition:Vec3;
	var transformedNormal:Vec3;
	var terrainNormal:Vec3;
	var pixelColor:Vec4;
	@input var input:{ var position : Vec3; var normal : Vec3};
	@global var global:{ @perObject
	var modelView : Mat4};
	@global var camera:{ var position : Vec3};
	function vertex() {
		calculatedUV = input.position.xy / primSize;
		worldUV = transformedPosition.xy;
		if (VERTEX_DISPLACEMENT) {
			transformedPosition += vec3(0, 0, textureLod(heightMap, calculatedUV, 0).r);
			terrainNormal = unpackNormal(textureLod(normalMap, calculatedUV, 0).rgba);
		} else {
			terrainNormal = normalize(input.normal * global.modelView.mat3());
		};
		var bitangent = normalize(cross(vec3(1, 0, 0), terrainNormal));
		var tangent = normalize(cross(terrainNormal, bitangent));
		TBN = mat3(vec3(tangent.x, bitangent.x, terrainNormal.x), vec3(tangent.y, bitangent.y, terrainNormal.y), vec3(tangent.z, bitangent.z, terrainNormal.z));
	};
	function getWeight(i:IVec3, uv:Vec2):Vec3 {
		var weight = vec3(0);
		weight.x = weightTextures.getLod(vec3(uv, i.x), 0).r;
		if (i.y != i.x) weight.y = weightTextures.getLod(vec3(uv, i.y), 0).r;
		if (i.z != i.x) weight.z = weightTextures.getLod(vec3(uv, i.z), 0).r;
		return weight;
	};
	function getDepth(i:IVec3, uv:Vec2):Vec3 {
		var depth = vec3(0);
		if (w.x > 0) depth.x = pbrTextures.getLod(getsurfaceUV(i.x, uv), 0).a;
		if (w.y > 0) depth.y = pbrTextures.getLod(getsurfaceUV(i.y, uv), 0).a;
		if (w.z > 0) depth.z = pbrTextures.getLod(getsurfaceUV(i.z, uv), 0).a;
		return 1 - depth;
	};
	var w:Vec3;
	var i:IVec3;
	function getPOMUV(i:IVec3, uv:Vec2):Vec2 {
		var viewNS = normalize(camera.position - transformedPosition) * TBN;
		viewNS.xy /= viewNS.z;
		viewNS.x *= -1;
		var numLayers = mix(float(maxStep), float(minStep), saturate(viewNS.dot(terrainNormal)));
		var layerDepth = 1.0 / numLayers;
		var curLayerDepth = 0.;
		var delta = (viewNS.xy * parallaxAmount / primSize) / numLayers;
		var curUV = uv;
		var depth = getDepth(i, curUV);
		var curDepth = depth.dot(w);
		var prevDepth = 0.;
		while (curLayerDepth < curDepth) {
			curUV += delta;
			prevDepth = curDepth;
			i = ivec3(surfaceIndexMap.getLod(curUV, 0).rgb * 255);
			w = getWeight(i, curUV);
			depth = getDepth(i, curUV);
			curDepth = depth.dot(w);
			curLayerDepth += layerDepth;
		};
		var prevUV = curUV - delta;
		var after = curDepth - curLayerDepth;
		var before = prevDepth - curLayerDepth + layerDepth;
		var pomUV = mix(curUV, prevUV, after / (after - before));
		return pomUV;
	};
	function getsurfaceUV(id:Int, uv:Vec2):Vec3 {
		uv = transformedPosition.xy + (uv * primSize - input.position.xy);
		var angle = surfaceParams[id].w;
		var offset = vec2(surfaceParams[id].y, surfaceParams[id].z);
		var tilling = surfaceParams[id].x;
		var worldUV = uv * tilling + offset;
		var res = vec2(worldUV.x * cos(angle) - worldUV.y * sin(angle), worldUV.y * cos(angle) + worldUV.x * sin(angle));
		var surfaceUV = vec3(res % 1, id);
		return surfaceUV;
	};
	function fragment() {
		if (CHECKER) {
			var tile = abs(abs(floor(input.position.x)) % 2 - abs(floor(input.position.y)) % 2);
			pixelColor = vec4(mix(vec3(0.4), vec3(0.1), tile), 1.0);
			roughness = mix(0.1, 0.9, tile);
			metalness = mix(1.0, 0, tile);
			occlusion = 1;
			emissive = 0;
		} else if (COMPLEXITY) {
			var blendCount = 0 + weightTextures.get(vec3(0)).r * 0;
			for (i  in  0 ... SURFACE_COUNT) blendCount += ceil(weightTextures.get(vec3(calculatedUV, i)).r);
			pixelColor = vec4(mix(vec3(0, 1, 0), vec3(1, 0, 0), blendCount / 3.0), 1);
			emissive = 1;
			roughness = 1;
			metalness = 0;
			occlusion = 1;
		} else {
			i = ivec3(surfaceIndexMap.get(calculatedUV).rgb * 255);
			w = getWeight(i, calculatedUV);
			var pomUV = PARALLAX ? getPOMUV(i, calculatedUV) : calculatedUV;
			if (PARALLAX) {
				i = ivec3(surfaceIndexMap.get(pomUV).rgb * 255);
				w = getWeight(i, pomUV);
			};
			var h = vec3(0);
			var surfaceUV1 = getsurfaceUV(i.x, pomUV);
			var surfaceUV2 = getsurfaceUV(i.y, pomUV);
			var surfaceUV3 = getsurfaceUV(i.z, pomUV);
			var pbr1 = vec4(0), pbr2 = vec4(0), pbr3 = vec4(0);
			if (w.x > 0) pbr1 = pbrTextures.get(surfaceUV1).rgba;
			if (w.y > 0) pbr2 = pbrTextures.get(surfaceUV2).rgba;
			if (w.z > 0) pbr3 = pbrTextures.get(surfaceUV3).rgba;
			var h = vec3(secondSurfaceParams[i.x].x + pbr1.a * (secondSurfaceParams[i.x].y - secondSurfaceParams[i.x].x), secondSurfaceParams[i.y].x + pbr2.a * (secondSurfaceParams[i.y].y - secondSurfaceParams[i.y].x), secondSurfaceParams[i.z].x + pbr3.a * (secondSurfaceParams[i.z].y - secondSurfaceParams[i.z].x));
			var h = mix(vec3(1, 1, 1), h, heightBlendStrength);
			w *= h;
			var ws = mix(w, w, blendSharpness);
			var m = max(w.x, max(w.y, w.z));
			var mw = vec3(0, 0, 0);
			if (m == w.x) mw = vec3(1, 0, 0);
			if (m == w.y) mw = vec3(0, 1, 0);
			if (m == w.z) mw = vec3(0, 0, 1);
			w = mix(w, mw, blendSharpness);
			var albedo = vec3(0);
			var normal = vec3(0);
			var pbr = vec4(0);
			if (w.x > 0) {
				albedo += albedoTextures.get(surfaceUV1).rgb * w.x;
				normal += unpackNormal(normalTextures.get(surfaceUV1).rgba) * w.x;
				pbr += pbr1 * w.x;
			};
			if (w.y > 0) {
				albedo += albedoTextures.get(surfaceUV2).rgb * w.y;
				normal += unpackNormal(normalTextures.get(surfaceUV2).rgba) * w.y;
				pbr += pbr2 * w.y;
			};
			if (w.z > 0) {
				albedo += albedoTextures.get(surfaceUV3).rgb * w.z;
				normal += unpackNormal(normalTextures.get(surfaceUV3).rgba) * w.z;
				pbr += pbr3 * w.z;
			};
			var wSum = w.x + w.y + w.z;
			albedo /= wSum;
			pbr /= wSum;
			normal /= wSum;
			normal = normal.normalize();
			transformedNormal = normalize(normal * TBN);
			pixelColor = vec4(albedo, 1.0);
			if (GLOSS) roughness = 1 - pbr.g * pbr.g else roughness = pbr.g;
			metalness = pbr.r;
			occlusion = pbr.b;
			emissive = 0;
		};
		if (SHOW_GRID) {
			var gridColor = vec4(1, 0, 0, 1);
			var tileEdgeColor = vec4(1, 1, 0, 1);
			var grid:Vec2 = ((input.position.xy.mod(cellSize.xy) / cellSize.xy) - 0.5) * 2.0;
			grid = ceil(max(vec2(0), abs(grid) - 0.9));
			var tileEdge = max((1 - ceil(input.position.xy / primSize - 0.1 / (primSize / cellSize))), floor(input.position.xy / primSize + 0.1 / (primSize / cellSize)));
			emissive = max(max(grid.x, grid.y), max(tileEdge.x, tileEdge.y));
			pixelColor = mix(pixelColor, gridColor, clamp(0, 1, max(grid.x, grid.y)));
			pixelColor = mix(pixelColor, tileEdgeColor, clamp(0, 1, max(tileEdge.x, tileEdge.y)));
			metalness = mix(metalness, 0, emissive);
			roughness = mix(roughness, 1, emissive);
			occlusion = mix(occlusion, 1, emissive);
			transformedNormal = mix(transformedNormal, vec3(0, 1, 0), emissive);
		};
	};
}

{
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	@param var texture:Sampler2D;
	function fragment() {
		var tex = texture.get(calculatedUV);
		pixelColor.rgba *= tex.rgba;
	};
}

{
	@param @range(0, 360) var rotate = 0.0;
	@param var rotateCenter:Vec2 = vec2(0.5, 0.5);
	@const var flipX:Bool;
	@const var flipY:Bool;
	var calculatedUV:Vec2;
	function fragment() {
		var a = rotate * 2 * 3.14159265 / 360.0;
		var m = mat2(vec2(cos(a), -sin(a)), vec2(sin(a), cos(a)));
		var uv = calculatedUV;
		if (flipX) uv.x = 1 - uv.x;
		if (flipY) uv.y = 1 - uv.y;
		calculatedUV = (uv - rotateCenter) * m + rotateCenter;
	};
}

{
	var pixelColor:Vec4;
	var calculatedUV:Vec2;
	function fragment() {
		var uv = calculatedUV;
		pixelColor.rgb = vec3(uv.x % 1.0, uv.y, 0.0);
	};
}

{
	function getCoef(shCoords:Vec3, band:Int):Vec3 {
		var u = (shCoords.x + band * lightmapSize.x) * texelSize.x + texelSize.x / 2.0;
		var v = (shCoords.y + shCoords.z * lightmapSize.y) * texelSize.y + texelSize.y / 2.0;
		return lightProbeTexture.get(vec2(u, v)).rgb;
	};
	function getCoefFinal(band:Int):Vec3 {
		var p00 = mix(getCoef(p000, band), getCoef(p100, band), dist.x);
		var p01 = mix(getCoef(p001, band), getCoef(p101, band), dist.x);
		var p10 = mix(getCoef(p010, band), getCoef(p110, band), dist.x);
		var p11 = mix(getCoef(p011, band), getCoef(p111, band), dist.x);
		var p0 = mix(p00, p10, dist.y);
		var p1 = mix(p01, p11, dist.y);
		var p = mix(p0, p1, dist.z);
		return p;
	};
	function computeIrradiance(norm:Vec3):Vec3 {
		var c1 = 0.429043;
		var c2 = 0.511664;
		var c3 = 0.743125;
		var c4 = 0.886227;
		var c5 = 0.247708;
		var irradiance = vec3(0, 0, 0);
		if (ORDER >= 1) {
			var L00 = getCoefFinal(0);
			irradiance += c4 * L00;
		};
		if (ORDER >= 2) {
			var L1n1 = getCoefFinal(1);
			var L10 = getCoefFinal(2);
			var L11 = getCoefFinal(3);
			irradiance += 2 * c2 * (L11 * norm.x + L1n1 * norm.y + L10 * norm.z);
		};
		if (ORDER >= 3) {
			var L2n2 = getCoefFinal(4);
			var L2n1 = getCoefFinal(5);
			var L20 = getCoefFinal(6);
			var L21 = getCoefFinal(7);
			var L22 = getCoefFinal(8);
			irradiance += c1 * L22 * (norm.x * norm.x - norm.y * norm.y) + c3 * L20 * (norm.z * norm.z) - c5 * L20 + 2 * c1 * (L2n2 * (norm.x * norm.y) + L21 * (norm.x * norm.z) + L2n1 * (norm.y * norm.z));
		};
		return irradiance / 3.14;
	};
	function getLightProbeIndex(coords:Vec3):Int {
		return int(floor(coords.x + lightmapSize.x * coords.y + lightmapSize.y * lightmapSize.x * coords.z));
	};
	function getVoxelCoords(pos:Vec3):Vec3 {
		posLightmapSpace = (vec4(pos, 1) * lightmapInvPos).xyz;
		return floor(posLightmapSpace * (lightmapSize - vec3(1, 1, 1)));
	};
	function getLightProbePosition(coords:Vec3):Vec3 {
		return coords * voxelSize;
	};
	function getPixelPosition():Vec3 {
		var uv2 = (screenUV - 0.5) * vec2(2, -2);
		var temp = vec4(uv2, depth, 1) * cameraInverseViewProj;
		var originWS = temp.xyz / temp.w;
		return originWS;
	};
	function getClampedCoords(coords:Vec3):Vec3 {
		return min(lightmapSize - vec3(1, 1, 1), max(vec3(0, 0, 0), coords));
	};
	@const var ORDER:Int;
	@param var lightProbeTexture:Sampler2D;
	@param var lightmapInvPos:Mat4;
	@param var lightmapSize:Vec3;
	@param var voxelSize:Vec3;
	@param var strength:Float;
	@param var cameraInverseViewProj:Mat4;
	@param var cameraPos:Vec3;
	var transformedPosition:Vec3;
	var screenUV:Vec2;
	var depth:Float;
	var normal:Vec3;
	var position:Vec3;
	var posLightmapSpace:Vec3;
	var voxelCoords:Vec3;
	var albedo:Vec3;
	var occlusion:Float;
	var roughness:Float;
	var metalness:Float;
	var probeCount:Float;
	var coefCount:Float;
	var texelSize:Vec2;
	var dist:Vec3;
	var p000:Vec3;
	var p100:Vec3;
	var p010:Vec3;
	var p001:Vec3;
	var p110:Vec3;
	var p101:Vec3;
	var p011:Vec3;
	var p111:Vec3;
	var output:{ var color : Vec4};
	function fragment() {
		position = getPixelPosition();
		voxelCoords = getVoxelCoords(position);
		probeCount = lightmapSize.x * lightmapSize.y * lightmapSize.z;
		coefCount = float(ORDER * ORDER);
		texelSize = vec2(1 / (lightmapSize.x * coefCount), 1 / (lightmapSize.y * lightmapSize.z));
		if (posLightmapSpace.x < 0 || posLightmapSpace.y < 0 || posLightmapSpace.z < 0 || posLightmapSpace.x > 1 || posLightmapSpace.y > 1 || posLightmapSpace.z > 1) discard;
		p000 = getClampedCoords(voxelCoords + vec3(0, 0, 0));
		p100 = getClampedCoords(voxelCoords + vec3(1, 0, 0));
		p010 = getClampedCoords(voxelCoords + vec3(0, 1, 0));
		p001 = getClampedCoords(voxelCoords + vec3(0, 0, 1));
		p110 = getClampedCoords(voxelCoords + vec3(1, 1, 0));
		p101 = getClampedCoords(voxelCoords + vec3(1, 0, 1));
		p011 = getClampedCoords(voxelCoords + vec3(0, 1, 1));
		p111 = getClampedCoords(voxelCoords + vec3(1, 1, 1));
		var voxelPos = (voxelCoords) / (lightmapSize - vec3(1, 1, 1));
		dist = (posLightmapSpace - voxelPos) * (lightmapSize - vec3(1, 1, 1));
		var irradiance:Vec3 = computeIrradiance(normal) * min(vec3(1), albedo) * occlusion;
		var NdV = dot(normal, normalize(cameraPos - position));
