		var F = F0 + (max(vec3(1 - roughness), F0) - F0) * exp2((-5.55473 * NdV - 6.98316) * NdV);
		var indirect = (irradiance * (1 - metalness) * (1 - F)) * strength;
		output.color.rgb += indirect;
	};
}

